// Parameters
float edgeThreshold = 0.4; // Adjust for edge sensitivity
float brightness = 0.2;    // Adjust for brightness
float contrast = 2.5;

// Helper function to convert RGB to HSV
vec3 rgb2hsv(vec3 c)
{
    vec4 K = vec4(0.0, -1.0 / 3.0, 2.0 / 3.0, -1.0);
    vec4 p = mix(vec4(c.bg, K.wz), vec4(c.gb, K.xy), step(c.b, c.g));
    vec4 q = mix(vec4(p.xyw, c.r), vec4(c.r, p.yzx), step(p.x, c.r));

    float d = q.x - min(q.w, q.y);
    float e = 1.0e-10;
    return vec3(abs(q.z + (q.w - q.y) / (6.0 * d + e)), d / (q.x + e), q.x);
}

// Helper function to convert HSV to RGB
vec3 hsv2rgb(vec3 c)
{
    vec4 K = vec4(1.0, 2.0 / 3.0, 1.0 / 3.0, 3.0);
    vec3 p = abs(fract(c.xxx + K.xyz) * 6.0 - K.www);
    return c.z * mix(K.xxx, clamp(p - K.xxx, 0.0, 1.0), c.y);
}

// Function to increase saturation
vec3 boostSaturation(vec3 color, float amount)
{
    vec3 hsv = rgb2hsv(color);
    hsv.y *= amount; // Increase saturation
    return hsv2rgb(hsv);
}

// Modified Gaussian Blur Function for low saturation areas
vec3 selectiveGaussianBlur(vec2 uv, vec3 color, float saturationThreshold, float blurAmount)
{
    vec3 blurredColor = vec3(0.0);
    vec2 blurSize = vec2(blurAmount) / iResolution.xy; // Adjust blur size as needed

    for (int x = -1; x <= 1; x++)
    {
        for (int y = -1; y <= 1; y++)
        {
            vec2 offset = vec2(float(x), float(y)) * blurSize;
            vec3 neighborColor = texture(iChannel0, uv + offset).rgb;

            // Check if the color is of low saturation
            if (rgb2hsv(neighborColor).y < saturationThreshold)
            {
                blurredColor += neighborColor;
            }
            else
            {
                blurredColor += color; // Keep original color if saturation is high
            }
        }
    }

    return blurredColor / 9.0; // Average of 3x3 kernel
}

// Function to adjust brightness
vec3 adjustBrightness(vec3 color)
{
    return color + brightness;
}

// Function to adjust contrast
vec3 adjustContrast(vec3 color)
{
    return (color - 0.5) * contrast + 0.5;
}

// Edge Detection Function with Adjusted Scale Factor
float edgeDetection(vec2 uv)
{
    vec3 edgeColor = vec3(0.0);
    vec2 texelSize = 1.0 / iResolution.xy;

    // Adjust this scale factor to control edge detection sensitivity
    float scaleFactor = 1.5; // This value may need tweaking

    for (int x = -1; x <= 1; x++)
    {
        for (int y = -1; y <= 1; y++)
        {
            vec2 offset = scaleFactor * vec2(x, y) * texelSize;
            vec3 neighborColor = texture(iChannel0, uv + offset).rgb;
            edgeColor += abs(neighborColor - texture(iChannel0, uv).rgb);
        }
    }

    float edgeStrength = length(edgeColor);
    return edgeStrength > edgeThreshold ? 1.0 : 0.0;
}


// Color Quantization Function
vec3 quantizeColor(vec3 color)
{
    int numColors = 3; // Adjust for color quantization level
    vec3 quantized = floor(color * float(numColors)) / float(numColors);
    return quantized;
}



void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord / iResolution.xy;
    vec4 webcamColor = texture(iChannel0, uv);

    // Boost saturation
    vec3 adjustedColor = adjustBrightness(webcamColor.rgb);
    adjustedColor = adjustContrast(adjustedColor);
    adjustedColor = boostSaturation(adjustedColor, 1.1); // Adjust the factor as needed

    // Selective blur on low saturation areas
    float saturationThreshold = 0.2; // Adjust as needed
    float blurAmount = 4.0; // Adjust blur amount
    vec3 colorAfterBlur = selectiveGaussianBlur(uv, adjustedColor, saturationThreshold, blurAmount);

    // Apply edge detection on the color after blur
    float edgeStrength = edgeDetection(uv);

    // Color quantization on color after blur and vibrancy adjustments
    vec3 quantizedColor = quantizeColor(colorAfterBlur);

    // Mix based on edge presence
    vec3 finalColor = mix(quantizedColor, vec3(0.0), 0.5 * edgeStrength);

    fragColor = vec4(finalColor, 1.0);
}
